enum class tier : std::uint8_t { travel = 0, minor = 1, major = 2, quest = 3 };

/// What a node's effect does (docs/economy/RESEARCH.md, section "Effects no system reads yet").
/// Whether code READS a row is nation_tech.cpp's declaration (`classify_effect`), not this table's.
/// `unlock_kit` (BL-1436): one row per kit item a node opens, the catalogue item id in `target`;
/// the kit catalogue (unit_designs.cpp) is the read path, this row its display.
enum class effect_kind : std::uint8_t { modifier = 0, unlock_recipe = 1, unlock_structure = 2, mechanic = 3, unread = 4, unlock_kit = 5 };
enum class effect_op : std::uint8_t { multiply = 0, add = 1 };

inline constexpr int node_count        = 54;
inline constexpr int max_groups        = 2; ///< Most requirement groups any node has.
inline constexpr int max_group_members = 1; ///< Most members any one group has.
inline constexpr int effect_count      = 56; ///< Rows in `effects` (a list scope is one row per member).

/// One node of the Early Space tree. `groups[g][m]` is a node index, -1 past the group's end;
/// a node is open when every one of its `group_count` groups has at least one held member.
struct node
{
    const char*  id;          ///< Store id, e.g. "DG-PR-EX-A". The key `condition_subject::research` names.
    const char*  name;
    tier         t;
    std::uint8_t ring;        ///< 1..4, inside out.
    std::uint8_t cost_units;  ///< Tier base x ring; RP cost = cost_units x the RP unit.
    std::uint8_t group_count; ///< Requirement groups in use (0 = a root).
    std::array<std::array<std::int16_t, max_group_members>, max_groups> groups;
    std::int16_t excludes;    ///< The pick-one pair sibling's index, or -1.
    bool         is_quest;
    bool         is_placeholder;
    bool         is_root;     ///< No requirements: a branch's first travel node.
    bool         is_mastery;
    bool         is_joint;
    const char*  branch;      ///< "PR-EX" etc.; "" for a joint.
    const char*  placeholder; ///< The system a placeholder holds the place of; "" otherwise.
    const char*  deed;        ///< A quest's deed prose; "" otherwise.
    const char*  advantage;   ///< The player-facing prose; `effects` is its machine form.
    std::uint16_t effect_begin; ///< This node's rows in `effects`: [effect_begin, effect_end).
    std::uint16_t effect_end;
    const char*  deed_waits_on; ///< A quest whose deed is declared unread: the system it waits on. "" otherwise.
};

/// One machine effect of one node. A modifier moves `subject` (a modifier_subject key) where its
/// `scope` matches: "all", "resource:<good>", "group:<recipe group>", "recipe:<recipe>",
/// "building:<type>", "site:<named extraction site>". An unlock names its recipe or structure in
/// `target`; a mechanic its key. `unread` names the system it waits on.
struct effect
{
    std::int16_t node;
    effect_kind  kind;
    const char*  subject;
    const char*  scope;
    effect_op    op;
    float        value;
    const char*  target;
    const char*  what;
    const char*  waits_on;
};

